begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Two lots. The southern lot, below Parking Lot Rock, is reached by following 3N07 to its end and suits low-clearance cars. The northern lot, via 3N16 and 3N32, suits high-clearance vehicles. The gate on Van Dusen Canyon Road locks after the first snowfall.' where id='ca_holcomb_valley_pinnacles' and id not in (select id from _had_note);
update public.areas set parking_note='Drive 2.3 miles east of Holcomb Valley Campground on 3N16 and park in the northwest-facing turnout on the north side of the road; the crag is about 0.1 mile north and visible from the road.' where id='ca_tanglewood_slabs_area' and id not in (select id from _had_note);
update public.areas set parking_note='Drive 2.3 miles east of Holcomb Valley Campground on 3N16 and park in the northwest-facing turnout on the north side of the road; the crag is about 0.1 mile north and visible from the road.' where path <@ (select path from public.areas where id='ca_tanglewood_slabs_area') and id <> 'ca_tanglewood_slabs_area' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='From the Highway 18 and 38 intersection, drive north a couple of blocks on Greenway Dr. to where it ends at Pioneer Lane, and park there.' where id='ca_north_shore_boulders' and id not in (select id from _had_note);
update public.areas set parking_note='From the Highway 18 and 38 intersection, drive north a couple of blocks on Greenway Dr. to where it ends at Pioneer Lane, and park there.' where path <@ (select path from public.areas where id='ca_north_shore_boulders') and id <> 'ca_north_shore_boulders' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Drive 3.2 miles east from the Van Dusen Canyon Rd and 3N16 intersection and park where 3N16 meets 3N02. Walk down into the stream bed and head east about 150 yards to the crags.' where id='ca_jacoby_canyon' and id not in (select id from _had_note);
update public.areas set parking_note='Drive 3.2 miles east from the Van Dusen Canyon Rd and 3N16 intersection and park where 3N16 meets 3N02. Walk down into the stream bed and head east about 150 yards to the crags.' where path <@ (select path from public.areas where id='ca_jacoby_canyon') and id <> 'ca_jacoby_canyon' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Drive about 3 miles east on 300 South in Smithfield from Main Street to the parking area at the Forest Service trailhead; the Dry Canyon trail starts there.' where id='ut_smithfield_dry_canyon' and id not in (select id from _had_note);
update public.areas set parking_note='Drive about 3 miles east on 300 South in Smithfield from Main Street to the parking area at the Forest Service trailhead; the Dry Canyon trail starts there.' where path <@ (select path from public.areas where id='ut_smithfield_dry_canyon') and id <> 'ut_smithfield_dry_canyon' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='From US-91 about 14.9 miles north of 400 N in Logan, turn east on High Creek Road (12100 N) and follow it 6.4 miles to the parking area; the last few miles are semi-rough dirt.' where id='ut_high_creek_canyon' and id not in (select id from _had_note);
update public.areas set parking_note='From US-91 about 14.9 miles north of 400 N in Logan, turn east on High Creek Road (12100 N) and follow it 6.4 miles to the parking area; the last few miles are semi-rough dirt.' where path <@ (select path from public.areas where id='ut_high_creek_canyon') and id <> 'ut_high_creek_canyon' and id not in (select id from _had_note) and id not in ('ut_cherry_peak','ut_high_creek_parking_lot_boulders','ut_parking_lot_boulder') and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park at the end of the cul-de-sac on 900 East above the Little Baldy subdivision in Providence (reached from 500 North or Center St), then hike about 0.35 mi on the trail.' where id='ut_hell_s_kitchen_cove' and id not in (select id from _had_note);
update public.areas set parking_note='Park at the end of the cul-de-sac on 900 East above the Little Baldy subdivision in Providence (reached from 500 North or Center St), then hike about 0.35 mi on the trail.' where path <@ (select path from public.areas where id='ut_hell_s_kitchen_cove') and id <> 'ut_hell_s_kitchen_cove' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
commit;
